def guard_dependencies(admission, phase):
    context, deps = admission['context'], admission['dependencies']
    if phase == 'qualify':
        require(deps == {}, 'Qualification may not consume a fitted checkpoint')
        return {}
    expected = {'warm': {'qualification'}, 'initialize': {'warm'}, 'fit': {'initialization'}}[phase]
    require(set(deps) == expected, 'Exact phase dependencies required')
    if phase == 'warm':
        qualifier, directory = verify_freeze(deps['qualification'], 'qualify', context)
        require(qualifier['passed'] is True and qualifier['qualification_only'] is True,
                'Whole-graph disposable qualification must pass before warm fit')
        return dict(qualification=qualifier, qualification_directory=directory)
    if phase == 'initialize':
        warm, directory = verify_freeze(deps['warm'], 'warm', context)
        qualifier, _ = verify_freeze(warm['qualification_freeze'], 'qualify', context)
        require(qualifier['passed'] is True, 'Qualified source context required')
        return dict(warm=warm, warm_directory=directory)
    initialization, directory = verify_freeze(deps['initialization'], 'initialize', context)
    warm, warm_directory = verify_freeze(initialization['warm_freeze'], 'warm', context)
    qualifier, _ = verify_freeze(warm['qualification_freeze'], 'qualify', context)
    require(initialization['passed'] is True and qualifier['passed'] is True
            and initialization['arm'] == admission['arm'], 'Exact qualified initialized arm required')
    return dict(initialization=initialization, initialization_directory=directory,
                warm=warm, warm_directory=warm_directory)

def declared_factor_names(backbone):
    """Only intermediate stem output and pre-class projector input scales.

    Raw boundary wrappers expose these names; pass TeacherFamily.boundary rather
    than the whole TeacherFamily (whose names have a boundary. prefix).
    Common K1 shapes: PolyFormer-Mono [(1,256),(1,256)] ->512;
    Polynormer-r [(1,512),(1,512)] ->1024 at its global phase. R/S identity initialization
    and warm bias copies are a separate mandatory caller operation. No reset
    after wrapping. Stem input R, head output S, and all B are excluded here.
    """
    if backbone == 'PolyFormer-Mono':
        return ('stem.S', 'head.R')
    if backbone == 'Polynormer-r':
        return ('stem.S', 'global_head.R')
    raise ValueError('Backbone/slice must be prospectively admitted')

def expected_attempts(contexts, anchor):
    rows = []
    for ctx in contexts:
        cell = ctx['graph']+'_seed'+str(ctx['seed'])
        for phase in ('qualify', 'warm', 'initialize', 'fit'):
            for arm in ARMS if phase in ('initialize', 'fit') else (None,):
                key = object_hash(dict(context_sha256=object_hash(ctx), phase=phase, arm=arm))
                output = anchor/phase/cell if arm is None else anchor/phase/cell/arm
                rows.append(dict(key=key, context_sha256=object_hash(ctx), phase=phase,
                                 arm=arm, output=str(output)))
    return sorted(rows, key=lambda row: row['key'])

class BoundaryProjector(nn.Module):
    """Shared W; private R/S/B. Author bias is copied into each private B row."""

    def __init__(self, native_linear, members, private_input_signs=False):
        super().__init__()
        if not isinstance(native_linear, nn.Linear):
            raise TypeError("This draft expects the pinned author's nn.Linear")
        self.members = int(members)
        self.weight = native_linear.weight
        self.R = nn.Parameter(self.weight.new_ones(members, self.weight.shape[1]))
        self.S = nn.Parameter(self.weight.new_ones(members, self.weight.shape[0]))
        bias = native_linear.bias
        if bias is None:
            bias = self.weight.new_zeros(self.weight.shape[0])
        self.B = nn.Parameter(bias.detach().expand(members, -1).clone())
        if private_input_signs:
            with torch.no_grad():
                self.R.bernoulli_(0.5).mul_(2).sub_(1)

    def forward(self, x, member):
        if not 0 <= member < self.members:
            raise IndexError("member outside admitted range")
        return F.linear(x * self.R[member], self.weight) * self.S[member] + self.B[member]

class PolyFormerBoundaryFamily(nn.Module):
    """Pinned native blocks retain [node, token, hidden] axes per member."""

    def __init__(self, fresh_native_model, members=4):
        super().__init__()
        self.core = fresh_native_model
        self.members = members
        self.stem = BoundaryProjector(self.core.lin1, members, private_input_signs=True)
        self.head = BoundaryProjector(self.core.lin3, members)
        # Transfer ownership: dormant author boundaries must not remain registered.
        self.core.lin1 = nn.Identity()
        self.core.lin3 = nn.Identity()

    def forward_member(self, tokens, member):
        if tokens.ndim != 3 or tokens.shape[1] != self.core.K:
            raise ValueError("tokens must be [N, author K+1, F]")
        x = self.stem(tokens, member)
        for block in self.core.attn:
            x = block(x)
        x = x.sum(dim=1)
        x = F.dropout(x, self.core.dropout, training=self.training)
        x = F.relu(self.core.lin2(x))
        x = F.dropout(x, self.core.dropout, training=self.training)
        return self.head(x, member)

    def forward(self, tokens):
        return torch.stack([self.forward_member(tokens, m) for m in range(self.members)], dim=0)


class PolynormerBoundaryFamily(nn.Module):
    """Pinned native local/global bodies run complete [node, hidden] trajectories."""

    def __init__(self, fresh_native_model, members=4):
        super().__init__()
        self.core = fresh_native_model
        self.members = members
        self.stem = BoundaryProjector(self.core.lin_in, members, private_input_signs=True)
        self.local_head = BoundaryProjector(self.core.pred_local, members)
        self.global_head = BoundaryProjector(self.core.pred_global, members)
        self.core.lin_in = nn.Identity()
        self.core.pred_local = nn.Identity()
        self.core.pred_global = nn.Identity()

    def set_global_stage(self, enabled):
        # Driver must bind this flag explicitly in checkpoint metadata.
        self.core._global = bool(enabled)

    def forward_member(self, features, edge_index, member):
        c = self.core
        x = F.dropout(features, p=c.in_drop, training=self.training)
        x = self.stem(x, member)
        x = F.dropout(x, p=c.dropout, training=self.training)
        x_local = 0
        for i, local_conv in enumerate(c.local_convs):
            if c.pre_ln:
                x = c.pre_lns[i](x)
            h = F.relu(c.h_lins[i](x))
            x = F.relu(local_conv(x, edge_index) + c.lins[i](x))
            x = F.dropout(x, p=c.dropout, training=self.training)
            beta = (torch.sigmoid(c.betas[i]) if c.beta < 0 else c.betas[i]).unsqueeze(0)
            x = (1 - beta) * c.lns[i](h * x) + beta * x
            x_local = x_local + x
        if c._global:
            return self.global_head(c.global_attn(c.ln(x_local)), member)
        return self.local_head(x_local, member)

    def forward(self, features, edge_index):
        return torch.stack(
            [self.forward_member(features, edge_index, m) for m in range(self.members)], dim=0
        )

def clone_boundary(native_teacher, boundary_api, members):
    """Never reset, consume or mutate the donor; construction RNG is restored later."""
    backbone = native_teacher.specification['backbone']
    require(native_teacher.members == 1 and len(native_teacher.models) == 1,
            'Warm donor must be the native single predictor')
    donor = native_teacher.models[0]
    for boundary in BOUNDARIES[backbone]:
        require(getattr(donor, boundary).bias is not None, 'Admitted native boundary must have bias')
    if members == 4:
        raw = boundary_api.clone_warm_native_boundary(donor, backbone, members=4)
    else:
        require(members == 1, 'Only K1 AD and K4 continuation clones are admitted')
        constructor = (boundary_api.PolyFormerBoundaryFamily if backbone == 'polyformer_mono'
                       else boundary_api.PolynormerBoundaryFamily)
        raw = boundary_api.set_boundary_identity_(constructor(copy.deepcopy(donor), members=1))
        raw.train(donor.training)
    if backbone == 'polynormer_r':
        raw.set_global_stage(native_teacher.global_stage)
    return raw

def alias_inventory(model):
    """Canonical first name plus every alias; no assumed parameter order."""
    groups, by_id = [], {}
    for name, parameter in model.named_parameters(remove_duplicate=False):
        identity = id(parameter)
        if identity not in by_id:
            by_id[identity] = len(groups)
            groups.append(dict(name=name, aliases=[], shape=list(parameter.shape),
                               requires_grad=parameter.requires_grad))
        groups[by_id[identity]]['aliases'].append(name)
    return groups


def named_optimizer_snapshot(model, optimizer):
    import torch
    inventory = alias_inventory(model)
    names = {id(parameter): name for name, parameter in model.named_parameters()}
    seen, groups, states = set(), [], {}
    for group in optimizer.param_groups:
        group_names = []
        for parameter in group['params']:
            require(id(parameter) in names and id(parameter) not in seen,
                    'Optimizer must cover each registered parameter once')
            seen.add(id(parameter))
            name = names[id(parameter)]
            group_names.append(name)
            states[name] = cpu_copy(optimizer.state.get(parameter, {}))
            require(set(states[name]) <= {'step', 'exp_avg', 'exp_avg_sq', 'max_exp_avg_sq'},
                    'Only ordinary Adam state is admitted')
            for key in ('exp_avg', 'exp_avg_sq', 'max_exp_avg_sq'):
                if key in states[name]:
                    require(states[name][key].shape == parameter.shape,
                            'Moment/parameter shape mismatch')
        groups.append(dict(names=group_names, options=cpu_copy(
            {key: value for key, value in group.items() if key not in ('params', 'param_names')})))
    require(seen == {id(parameter) for parameter in model.parameters()},
            'Optimizer omitted a native or inactive parameter')
    require(isinstance(optimizer, torch.optim.Adam), 'Only pinned coupled Adam is admitted')
    return dict(schema='named-aliased-adam-v1', aliases=inventory, groups=groups, state=states)

def failure_locals(error):
    """Retain in-flight method stats/epochs from exceptions without editing method."""
    result, frame = [], error.__traceback__
    while frame is not None:
        values = frame.tb_frame.f_locals
        keep = {key: json_safe(values[key]) for key in ('stats', 'records', 'counter', 'epoch', 'completed',
                'total_updates', 'stage', 'attempt', 'branch', 'best_epoch') if key in values}
        if keep:
            result.append(dict(function=frame.tb_frame.f_code.co_name, line=frame.tb_lineno, partial=keep))
        frame = frame.tb_next
    return result
